const maxTries = 3;
const workflow = 'PROJETO_SM3_02B_STRUCTURAL_BACKFILL_V2';

function compactError(x) {
  const e = x.error || x;
  const code = String(e.code || e.name || x.code || 'STRUCTURAL_DRIVE_DOWNLOAD_FAILED').slice(0, 200);
  let msg = String(e.message || x.message || e.description || 'Terminal failure after retries.');
  if (msg.length > 4000) msg = msg.slice(0, 4000);
  return {code, msg};
}

